  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Choosing a Topic, Purpose and Audience$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "Every good speech starts with three questions: What is my topic? What is my purpose? Who is my audience? Proverbs 16:23 says, The heart of the wise teacheth his mouth, and addeth learning to his lips. A wise speaker thinks before speaking.\n\nChoosing a topic is easier when you start with what you know and care about. List your interests, experiences, skills and concerns. Then ask whether the topic is right for the audience, the occasion and the time limit. A topic that is too broad, such as sports, cannot be covered in five minutes. Narrow it step by step: sports, then basketball, then how to improve free throw shooting. A good topic is interesting to you, useful to listeners and possible to research.\n\nNext, decide on a general purpose. An informative speech teaches or explains. A persuasive speech moves listeners to believe or do something. An entertaining or special occasion speech honors, celebrates or amuses. Then write a specific purpose statement that names what the audience will understand, believe or do. For example: After my speech, the audience will be able to name three steps for preparing a family hurricane kit. Finally, write a central idea in one sentence that sums up the main message, such as, A hurricane kit with water, food and papers can protect a family.\n\nAudience analysis helps you adapt. Consider demographics, such as age, education, background and group membership. Consider what the audience already knows, believes and cares about, and what they need from the speech. Think about the setting: the size of the room, the time of day and whether the audience is willing or reluctant. A talk to young children needs simple words and stories. A talk to business leaders needs clear facts and respect for their time. Ask yourself, why should they care? Adapting to the audience does not mean changing the truth. It means choosing the best way to communicate it. The Apostle Paul showed this skill. In 1 Corinthians 9:22 he wrote, I am made all things to all men, that I might by all means save some.\n\nYour task: (1) Narrow a broad topic in three steps. (2) Write a specific purpose and a central idea. (3) List four things to learn about an audience.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Proverbs 16:23 says, The heart of the wise teacheth his mouth, and addeth learning to his lips. A wise speaker thinks before speaking.\n\nNow watch this. Three questions start every speech. What is my topic? What is my purpose? Who is my audience?\n\nChoose a topic you know and care about. Narrow it. Sports is too broad. Basketball is better. How to improve free throw shooting fits five minutes. A good topic is interesting to you, useful to listeners and possible to research.\n\nPick a general purpose: inform, persuade or celebrate. Then write a specific purpose, such as, the audience will be able to name three steps for preparing a family hurricane kit. Write a central idea in one sentence.\n\nAnalyze your audience. Age, education, background, what they know and what they care about. Think about the setting and ask, why should they care? Adapting does not mean changing the truth. Paul wrote in 1 Corinthians 9:22, I am made all things to all men, that I might by all means save some.\n\nYour task is to narrow a topic, write a purpose and central idea and list audience factors. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Choosing a Topic, Purpose and Audience$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Research and Credible Sources$j$, $j${"readings": [{"title": "Acts 17 (King James Version)", "url": "/portal/bible/Acts/17"}], "body": "A speaker earns trust by getting the facts right. Acts 17:22 to 31 records how Paul spoke on Mars' Hill in Athens. He had observed the city, read its poets and knew its altars. Acts 17:23 says, For as I passed by, and beheld your devotions, I found an altar with this inscription, TO THE UNKNOWN GOD. Paul did his homework. Good research gives a speaker substance and confidence.\n\nBegin by listing what you already know and what you need to find out. Then gather information from several kinds of sources. Primary sources are original materials, such as interviews, speeches, letters, data and eyewitness reports. Secondary sources explain or interpret primary sources, such as textbooks, news analysis and encyclopedias. Libraries, school databases, government websites and respected organizations are good places to start. Interviewing an expert, a pastor or a community leader can add fresh material.\n\nNot every source is reliable. Test each one with the CRAAP checklist. Currency: is the information up to date for this topic? Relevance: does it fit your purpose? Authority: who wrote it, and what are the author's credentials? Accuracy: is it supported by evidence, and can you confirm it elsewhere? Purpose: is the source trying to inform, sell or persuade? Web addresses ending in .gov or .edu are often reliable, but even these need checking. Be careful with social media posts, anonymous pages and sites that exist to sell something. Check a claim in at least two good sources. Be careful with statistics. Ask who gathered them, how many people were counted and whether the numbers are being used fairly.\n\nTake notes in your own words, and copy exact words only inside quotation marks with the source written down. Record the author, title, date and web address for each source. This protects you from plagiarism and lets you build a bibliography. In the speech, name your sources aloud. Tools that use artificial intelligence can suggest ideas, but they can also invent facts and sources. Always confirm in a real source before you speak.\n\nYour task: (1) Tell the difference between primary and secondary sources. (2) Apply the five CRAAP questions to a source. (3) Explain how to record sources.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Acts 17:23 says, For as I passed by, and beheld your devotions, I found an altar with this inscription, TO THE UNKNOWN GOD. Paul did his homework before he spoke on Mars' Hill.\n\nNow watch this. Start with what you know and what you need to find out. Primary sources are original materials like interviews, speeches, letters and data. Secondary sources explain or interpret them, like textbooks and news analysis. Start with libraries, school databases, government websites and respected organizations. Interview an expert.\n\nTest each source with CRAAP. Currency. Relevance. Authority. Accuracy. Purpose. Dot gov and dot edu are often reliable but still need checking. Be careful with social media and anonymous pages. Confirm claims in at least two good sources. Ask who gathered the statistics and how.\n\nTake notes in your own words. Copy exact words only in quotation marks. Record author, title, date and address. Name your sources aloud in the speech. AI tools can invent facts and sources, so confirm in a real source.\n\nYour task is to compare source types, apply CRAAP and explain how to record sources. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Research and Credible Sources$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Organizing: Introduction, Body and Conclusion$j$, $j${"readings": [{"title": "Luke 1 (King James Version)", "url": "/portal/bible/Luke/1"}], "body": "A speech without order is like a road without signs. Listeners get lost. Luke 1:3 and 4 shows the value of order. Luke wrote, It seemed good to me also, having had perfect understanding of all things from the very first, to write unto thee in order, most excellent Theophilus, That thou mightest know the certainty of those things, wherein thou hast been instructed. A clear order helps people understand and remember.\n\nMost speeches have three parts: introduction, body and conclusion. The introduction does four jobs. It gets attention with a story, a surprising fact, a question or a short quotation. It states the topic and why it matters. It builds the speaker's credibility by showing why the audience can trust what follows. It previews the main points. Avoid an apology such as, I am not very good at this.\n\nThe body holds the main points, usually two to five. Each main point should support the central idea and have its own evidence. Main points can be arranged in several ways. A chronological pattern follows time. A spatial pattern follows place. A topical pattern groups by category. A cause and effect pattern shows what happens and why. A problem and solution pattern describes a need and then a remedy. Choose the pattern that fits the topic. The rule of three, which uses three points, three steps or three examples, is easy to remember and pleasant to hear.\n\nThe conclusion should signal that the end is near with a phrase such as, In closing. It restates the central idea and summarizes the main points. Then it ends with a strong final thought that gives the audience something to remember, such as a call to action, a challenge, a vision or a return to the opening story. Never introduce new main points in the conclusion, and do not trail off with, That is all I have.\n\nSpeakers often say, tell them what you will tell them, tell them, then tell them what you told them. This repetition helps listeners who cannot go back and re read as they could with a page.\n\nYour task: (1) List the four jobs of an introduction. (2) Name three ways to arrange main points. (3) Describe what a strong conclusion includes.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Luke wrote in Luke 1:3 and 4 to write unto thee in order, most excellent Theophilus, that thou mightest know the certainty of those things, wherein thou hast been instructed. A clear order helps people understand and remember.\n\nNow watch this. A speech has an introduction, a body and a conclusion. The introduction gets attention, states the topic and why it matters, builds credibility and previews the main points. Do not start with an apology.\n\nThe body holds two to five main points. Arrange them by time, by place, by topic, by cause and effect or by problem and solution. The rule of three is easy to remember.\n\nThe conclusion signals the end, restates the central idea, summarizes the main points and finishes with a strong final thought, like a challenge or a return to the opening story. Never add new main points. Do not trail off.\n\nTell them what you will tell them, tell them, then tell them what you told them. Listeners cannot go back and re read.\n\nYour task is to list the jobs of an introduction, name patterns and describe a conclusion. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Organizing: Introduction, Body and Conclusion$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Outlines, Transitions and Supporting Material$j$, $j${"readings": [{"title": "Ecclesiastes 12 (King James Version)", "url": "/portal/bible/Ecclesiastes/12"}], "body": "An outline is the skeleton of a speech. Ecclesiastes 12:10 says, The preacher sought to find out acceptable words: and that which was written was upright, even words of truth. Careful planning leads to words that are acceptable and true.\n\nA full sentence outline helps you plan, and a brief key word outline helps you speak. A standard outline uses Roman numerals for main points (I, II, III), capital letters for subpoints (A, B, C) and numbers for details (1, 2, 3). Each level must follow the rule of subordination, meaning that the lower level supports the higher level. It also follows the rule of division: if there is an A, there must be a B. Write the specific purpose and central idea at the top. Label the introduction, body and conclusion.\n\nSupporting material gives the main points strength. Examples are specific cases that make an idea clear. A story, whether true or carefully labeled as an illustration, helps listeners feel the point. Statistics are numbers that show size or trend, and they work best when rounded, compared and explained. Testimony from an expert, or a short quotation, adds authority. Definitions explain terms the audience may not know. Comparisons show how something unfamiliar is like something familiar. Visuals and demonstrations can show what words cannot. Using a mix of supporting material keeps the speech balanced and interesting.\n\nTransitions are the bridges between parts. A transition might be a word, such as first, next or finally, or a sentence, such as, Now that we have seen the problem, let us look at the solution. Internal previews tell what comes next, and internal summaries recall what was just covered. A signpost, such as, My second point is, helps listeners follow. Without transitions, the speech sounds like a pile of separate pieces.\n\nFinally, prepare delivery notes. Keep them brief, in large print, with key words and cues, such as pause here or show slide. A speaker who reads a full manuscript word for word can lose eye contact. A speaker who has only a few cues can look up and connect.\n\nYour task: (1) Build a short outline with two main points and subpoints. (2) Name four kinds of supporting material. (3) Write two transitions.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Ecclesiastes 12:10 says, The preacher sought to find out acceptable words: and that which was written was upright, even words of truth. Careful planning leads to words that are acceptable and true.\n\nNow watch this. An outline is the skeleton of a speech. Use Roman numerals for main points, capital letters for subpoints and numbers for details. Lower levels support higher levels. If there is an A, there must be a B. Put the specific purpose and central idea at the top.\n\nSupporting material gives main points strength. Use examples, stories, statistics, expert testimony, definitions, comparisons and visuals. Round the numbers, compare them and explain them.\n\nTransitions are bridges. Use words like first, next and finally. Use sentences like, now that we have seen the problem, let us look at the solution. Use internal previews, internal summaries and signposts.\n\nKeep delivery notes brief, in large print, with key words and cues like pause here. Looking up connects you with the audience.\n\nYour task is to build an outline, name supporting material and write two transitions. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Outlines, Transitions and Supporting Material$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Preparing a Speech$j$, $j${"prompt": "Write a report of at least 250 words that shows how to prepare a speech. Use complete sentences, label each part and include your own sample work. Proverbs 16:23 says, The heart of the wise teacheth his mouth, and addeth learning to his lips.\n\nPart 1: Choose a broad topic and narrow it in three steps. Write a general purpose, a specific purpose and a central idea. Describe your audience and how you will adapt to them.\nPart 2: Explain the difference between primary and secondary sources. List three sources you would use and apply the five CRAAP questions to one of them. Explain how you will record sources and avoid plagiarism.\nPart 3: Write a one paragraph introduction that includes an attention getter, a statement of why the topic matters, and a preview of the main points. Choose a pattern for the body and explain your choice.\nPart 4: Build an outline with a title, specific purpose, central idea, introduction, two main points with subpoints, and a conclusion. Include two kinds of supporting material and two transitions.\nPart 5: Write a conclusion paragraph with a restatement and a final thought. Explain how Luke 1:3 and 4 and Ecclesiastes 12:10 encourage careful planning.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 15 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Preparing a Speech$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Do Your Homework$j$, $j${"prompt": "Write a post of at least 120 words that (1) names a topic you would like to speak about and who your audience would be, (2) explains in your own words how you would tell whether a source is trustworthy, (3) explains why careful preparation honors God and respects an audience, and (4) connects your answer to Proverbs 16:23, Acts 17:23 or Luke 1:3 and 4. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How does good research protect a speaker from spreading false information? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Do Your Homework$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Choosing a Topic, Purpose and Audience$j$, $j${"questions": [{"q": "A topic that is too broad for a five minute speech is best handled by:", "options": ["Adding more topics", "Narrowing it step by step", "Reading a list", "Speaking faster"]}, {"q": "A statement of what the audience will understand, believe or do after the speech is the:", "options": ["Specific purpose", "Conclusion", "Transition", "Title"]}, {"q": "A persuasive speech is meant to:", "options": ["Entertain only", "Fill time", "Move listeners to believe or do something", "Teach a skill only"]}, {"q": "Audience analysis helps a speaker:", "options": ["Choose the best way to communicate the truth", "Change the facts", "Avoid preparation", "Insult listeners"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Choosing a Topic, Purpose and Audience$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,0}'::int[], array[$j$A narrow topic can be covered well.$j$,$j$The specific purpose guides every choice.$j$,$j$Persuasion seeks a change in belief or action.$j$,$j$Adapting the approach is not changing the truth.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Choosing a Topic, Purpose and Audience$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Research and Credible Sources$j$, $j${"questions": [{"q": "An original interview or a letter written by an eyewitness is a:", "options": ["Primary source", "Secondary source", "Rumor", "Opinion post"]}, {"q": "In the CRAAP checklist, the letter A that stands for authority asks:", "options": ["Is it new?", "Is it long?", "Is it popular?", "Who wrote it and what are the author's credentials?"]}, {"q": "A good way to verify a surprising claim is to:", "options": ["Share it right away", "Trust the first result", "Confirm it in at least two good sources", "Ignore the source"]}, {"q": "Why should a speaker record the author, title, date and address of a source?", "options": ["To avoid plagiarism and build a bibliography", "It is never needed", "To impress the audience", "To make notes longer"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Research and Credible Sources$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,0}'::int[], array[$j$Primary sources come directly from the event or person.$j$,$j$Authority is about the author's expertise.$j$,$j$Cross checking protects accuracy.$j$,$j$Records let you credit and find the source again.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Research and Credible Sources$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Organizing: Introduction, Body and Conclusion$j$, $j${"questions": [{"q": "Which is a job of the introduction?", "options": ["Get attention and preview the main points", "Read the sources aloud", "Say that is all I have", "Introduce new main points"]}, {"q": "Arranging main points by time order is a:", "options": ["Problem and solution pattern", "Topical pattern", "Chronological pattern", "Spatial pattern"]}, {"q": "A strong conclusion should:", "options": ["Apologize", "Add three new points", "Trail off", "Restate the central idea and end with a memorable final thought"]}, {"q": "The pattern that describes a need and then a remedy is:", "options": ["Spatial", "Topical", "Chronological", "Problem and solution"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Organizing: Introduction, Body and Conclusion$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,3}'::int[], array[$j$The introduction gets attention and previews the speech.$j$,$j$Chronological means in time order.$j$,$j$A conclusion ties the speech together.$j$,$j$It names the problem first and then the fix.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Organizing: Introduction, Body and Conclusion$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Outlines, Transitions and Supporting Material$j$, $j${"questions": [{"q": "In a standard outline, main points are marked with:", "options": ["Page numbers", "Roman numerals", "Smiley faces", "Only bullets"]}, {"q": "A sentence such as, Now that we have seen the problem, let us look at the solution is a:", "options": ["Transition", "Statistic", "Citation", "Source"]}, {"q": "Which is a form of supporting material?", "options": ["A joke with no point", "An expert quotation", "A long pause", "An apology"]}, {"q": "Delivery notes should be:", "options": ["Read word for word", "Left at home", "A full manuscript in tiny print", "Brief, in large print, with key words and cues"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Outlines, Transitions and Supporting Material$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,3}'::int[], array[$j$Roman numerals mark the main points.$j$,$j$Transitions link one part of the speech to the next.$j$,$j$Testimony adds authority.$j$,$j$Brief notes allow eye contact.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Outlines, Transitions and Supporting Material$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Preparing a Speech$j$, $j${"questions": [{"q": "Which topic is best narrowed for a five minute speech?", "options": ["All of history", "How to improve free throw shooting", "Sports", "Everything about weather"]}, {"q": "The one sentence summary of a speech's main message is the:", "options": ["Signpost", "Central idea", "Transition", "Source list"]}, {"q": "Authority in the CRAAP checklist asks about:", "options": ["The color of the page", "The length of the page", "The author's credentials", "The number of ads"]}, {"q": "A textbook that explains and interprets earlier research is a:", "options": ["Secondary source", "Raw data file", "Eyewitness report", "Primary source"]}, {"q": "Which is the best way to begin an introduction?", "options": ["With a story, question or surprising fact", "With the conclusion", "With a long list of sources", "With an apology"]}, {"q": "The rule of three means using:", "options": ["Three hours of practice", "Three apologies", "Three points, steps or examples", "Three sources only"]}, {"q": "In a full outline, if there is an A there must be a:", "options": ["Footnote", "B", "Number 10", "Roman numeral IV"]}, {"q": "An internal summary in the body of a speech:", "options": ["Ends the speech", "Recalls what was just covered", "Introduces a new topic", "Cites a source"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Preparing a Speech$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,2,0,0,2,1,1}'::int[], array[$j$A narrow topic fits the time limit.$j$,$j$The central idea sums up the message.$j$,$j$Credentials show whether the author is qualified.$j$,$j$Secondary sources interpret primary ones.$j$,$j$An attention getter draws listeners in.$j$,$j$Groups of three are easy to remember.$j$,$j$The rule of division requires at least two parts.$j$,$j$It reminds listeners of the point just made.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Preparing a Speech$j$ on conflict (item_id) do nothing;
